// Members of App. Storyboards remain local; only generation provenance is sent.
std::thread storyResolveThread;std::atomic_bool storyResolveCancel{false};bool storyResolveRunning=false;
std::map<fs::path,std::pair<fs::file_time_type,std::string>> imagePanelIds;
json storyResolveInput(){return {{"sections",wirePromptDrafts(store->state)},{"profile_ids",selectedProfiles(store->settings)},{"pipeline",modelId(store->settings)}};}
std::wstring storyboardTitle(){if(!store->hasStoryboard())return L"페이지·컷";auto& board=store->current()["storyboard"];size_t number=0;for(auto& page:board["pages"]){number++;if(str(page,"id")==str(board,"active_page"))break;}return L"P"+std::to_wstring(number)+L" · "+wide(str(activeBoardPanel(board),"name"));}
void afterStoryChange(){storyResolveCancel=true;clearProfileEdit();selected.clear();preview.Reset();imageW=imageH=0;refIndex=0;formScroll=0;rebuild(false);scan();auto value=store->state.value("selected",json(nullptr));if(value.is_string()){auto path=fs::path(wide(value.get<std::string>()));if(std::find(paths.begin(),paths.end(),path)!=paths.end())select(path);}status=L"컷 설정을 불러왔습니다.";}
void pinStoryEntities(){if(modelId(store->settings)=="pixel_art")throw std::runtime_error("픽셀아트에는 항목 기준 고정을 사용할 수 없습니다.");if(!developer())throw std::runtime_error("현재 계정은 항목 기준을 고정할 수 없습니다.");if(storyResolveRunning)throw std::runtime_error("항목 기준을 확인 중입니다.");save();if(!str(store->state,"_prompt_error").empty())throw std::runtime_error("프롬프트 항목 구분을 먼저 수정하세요.");if(storyResolveThread.joinable())storyResolveThread.join();auto input=storyResolveInput(),cfg=store->settings;auto scope=store->workspaceScope,channel=store->active,panel=store->activePanelId(),key=sha256(input.dump());if(store->state.contains("_entity_expectations"))input["previous"]=store->state["_entity_expectations"];storyResolveCancel=false;storyResolveRunning=true;auto* target=engine;
 storyResolveThread=std::thread([this,input,cfg,scope,channel,panel,key,target]{json data={{"scope",scope},{"channel",channel},{"panel",panel},{"input_key",key}};try{NetworkScope guard(&storyResolveCancel,std::chrono::steady_clock::now()+std::chrono::seconds(10),str(cfg,"content_mode","standard"));auto response=request("POST",joinUrl(str(cfg,"api"),"/learning/profiles/resolve"),str(cfg,"api_key"),input.dump(),"application/json",&storyResolveCancel,65536,10000);if(response.code==429)throw std::runtime_error("잠시 후 다시 시도하세요.");data["reply"]=response.object();}catch(const std::exception& e){data["error"]=storyResolveCancel?"항목 기준 확인을 취소했습니다.":userError(e.what());}target->event({"story_entities","","",data});});status=L"항목 기준 확인 중…";
}
void storyEntitiesReply(const Event& event){storyResolveRunning=false;if(str(event.data,"scope")!=store->workspaceScope||str(event.data,"channel")!=store->active||str(event.data,"panel")!=store->activePanelId())return;if(storyResolveCancel)return;if(event.data.contains("error")){status=wide(str(event.data,"error"));return;}sync();if(str(event.data,"input_key")!=sha256(storyResolveInput().dump())){status=L"입력이 바뀌었습니다. 항목 기준을 다시 고정하세요.";return;}auto reply=event.data.value("reply",json::object());auto snapshot=reply.value("snapshot",json::object());if(snapshot.value("version",0)!=1||!snapshot.contains("refs")||!snapshot["refs"].is_array()||snapshot["refs"].size()>10||snapshot.dump().size()>32768){status=L"서버의 항목 기준 응답을 확인하세요.";return;}store->state["_entity_expectations"]=snapshot;store->save();status=L"현재 컷의 항목 기준을 고정했습니다.";}
void storyboardMenu(){if(promptComposing)return;HMENU menu=CreatePopupMenu();std::vector<std::pair<std::string,std::string>> targets;if(store->hasStoryboard()){auto& board=store->current()["storyboard"];for(auto& page:board["pages"]){HMENU cuts=CreatePopupMenu();for(auto& panel:page["panels"]){targets.emplace_back(str(page,"id"),str(panel,"id"));AppendMenuW(cuts,MF_STRING|(str(panel,"id")==str(board,"active_panel")?MF_CHECKED:0),1000+targets.size()-1,wide(str(panel,"name")).c_str());}AppendMenuW(menu,MF_POPUP,(UINT_PTR)cuts,wide(str(page,"name")).c_str());}AppendMenuW(menu,MF_SEPARATOR,0,nullptr);for(auto [command,title]:std::vector<std::pair<int,const wchar_t*>>{{1,L"새 페이지"},{2,L"새 컷"},{3,L"컷 복제"},{4,L"페이지 이름 변경"},{5,L"컷 이름 변경"},{6,L"컷 삭제"},{7,L"페이지 삭제"},{8,L"삭제 되돌리기"},{9,L"상속 설정으로 복원"},{10,L"설정 복원 취소"},{11,L"현재 설정을 페이지 기준으로"},{12,L"현재 설정을 프로젝트 기준으로"},{15,L"페이지·컷 사용 안 함"}})AppendMenuW(menu,MF_STRING,command,title);}else AppendMenuW(menu,MF_STRING,1,L"페이지·컷 시작");AppendMenuW(menu,MF_STRING,16,L"페이지·컷 백업 복원");AppendMenuW(menu,MF_SEPARATOR,0,nullptr);AppendMenuW(menu,MF_STRING|(developer()&&modelId(store->settings)!="pixel_art"?0:MF_GRAYED),13,store->state.contains("_entity_expectations")?L"항목 기준 갱신":L"항목 기준 고정");AppendMenuW(menu,MF_STRING,14,L"항목 고정 해제");AppendMenuW(menu,MF_SEPARATOR,0,nullptr);AppendMenuW(menu,MF_STRING,20,L"오디션 · 후보 생성/평가");POINT point;GetCursorPos(&point);int command=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,point.x,point.y,0,hwnd,nullptr);DestroyMenu(menu);if(!command)return;if(command==20){auditionMenu();return;}if(engine->locked(store->active))throw std::runtime_error("생성·예약 작업을 마친 뒤 페이지나 컷을 바꿔 주세요.");if(command==13){pinStoryEntities();return;}save();if(command==16){auto file=fileDialog(hwnd,false,L"페이지·컷 백업\0*.json\0\0");if(file.empty())return;store->restoreStoryboardRecord(readJson(file));afterStoryChange();return;}if(command==14){store->state.erase("_entity_expectations");store->save();status=L"항목 고정을 해제했습니다.";return;}
 if(!store->hasStoryboard()){if(command==1){if(MessageBoxW(hwnd,L"현재 작업을 1페이지·1컷으로 유지하며 시작할까요?\n기존 프로젝트 파일을 백업합니다.",L"페이지·컷",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;store->enableStoryboard();afterStoryChange();}return;}
 if(command>=1000&&size_t(command-1000)<targets.size()){auto [page,panel]=targets[command-1000];store->selectBoard(page,panel);}else if(command==1){auto name=inputBox(hwnd,L"새 페이지 이름");if(name.empty())return;store->addBoardPage(utf8(name));}else if(command==2||command==3)store->addBoardPanel(command==3);else if(command==4||command==5){auto& board=store->current()["storyboard"];auto name=inputBox(hwnd,command==4?L"페이지 이름":L"컷 이름",wide(str(command==4?boardPage(board,str(board,"active_page")):activeBoardPanel(board),"name")));if(name.empty())return;store->renameBoard(command==4,utf8(name));}else if(command==6||command==7){if(MessageBoxW(hwnd,L"선택한 항목을 삭제할까요?\n이미지 파일은 보존하며 최근 삭제 10개는 되돌릴 수 있습니다.",L"페이지·컷 삭제",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;store->deleteBoard(command==7);}else if(command==8)store->undoBoardDelete();else if(command==9||command==10){store->resetBoardPanel(command==10);}else if(command==11||command==12){if(MessageBoxW(hwnd,L"현재 설정을 앞으로 만들 항목의 기준으로 저장할까요?\n기존 컷은 변경하지 않습니다.",L"기준 설정",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;store->boardDefaults(command==12);}else if(command==15){if(MessageBoxW(hwnd,L"현재 컷을 일반 작업으로 유지할까요?\n전체 페이지·컷은 백업하고 이미지 파일은 보존합니다.",L"페이지·컷 사용 안 함",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;store->disableStoryboard();}afterStoryChange();}
